// Core tests: the 12 literal core cases from fixtures.json (vendored
// verbatim from spec candidate e3be9220520a92b9b7b0de37c03bb0f2f26de76c;
// expected values taken from the file, never generated by the product),
// plus hand-derived boundary, validation-order, and invariant cases. The
// SPEC's own rules are the oracle; every extra expected value below was
// computed by hand from the SPEC's formulas and tables.

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/bodyfat.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
assert.equal(coreCases.length, 12);
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const man = {
  sex: "male",
  heightCm: "175",
  neckCm: "38",
  waistCm: "85",
  hipCm: "",
  weightKg: "75",
};
const woman = {
  sex: "female",
  heightCm: "162",
  neckCm: "32",
  waistCm: "72",
  hipCm: "95",
  weightKg: "58",
};

test("legal endpoints: height 100 and weight 25", () => {
  assert.deepEqual(
    run({ sex: "male", heightCm: "100", neckCm: "20", waistCm: "42", hipCm: "", weightKg: "25" }),
    { ok: true, result: { bodyFatPct: 5.7, category: "essential", fatMassKg: 1.4, leanMassKg: 23.6 } },
  );
});

test("legal endpoints: height 250, waist 300, weight 25", () => {
  assert.deepEqual(
    run({ sex: "male", heightCm: "250", neckCm: "20", waistCm: "300", hipCm: "", weightKg: "25" }),
    { ok: true, result: { bodyFatPct: 72.8, category: "obese", fatMassKg: 18.2, leanMassKg: 6.8 } },
  );
});

test("legal endpoints: neck 80 and weight 500", () => {
  assert.deepEqual(
    run({ sex: "male", heightCm: "250", neckCm: "80", waistCm: "300", hipCm: "", weightKg: "500" }),
    { ok: true, result: { bodyFatPct: 63.8, category: "obese", fatMassKg: 319.1, leanMassKg: 180.9 } },
  );
});

test("weight 500 with the man-normal measurements", () => {
  assert.deepEqual(run({ ...man, weightKg: "500" }), {
    ok: true,
    result: { bodyFatPct: 17, category: "fitness", fatMassKg: 85, leanMassKg: 415 },
  });
});

test("waist exactly equal to neck is LOG_DOMAIN", () => {
  assert.deepEqual(run({ ...man, neckCm: "40", waistCm: "40" }), {
    ok: false,
    error: { code: "LOG_DOMAIN", field: "waistCm", row: null },
  });
});

test("a negative computed percentage is IMPLAUSIBLE_RESULT", () => {
  assert.deepEqual(
    run({ sex: "male", heightCm: "250", neckCm: "79", waistCm: "80", hipCm: "", weightKg: "100" }),
    { ok: false, error: { code: "IMPLAUSIBLE_RESULT", field: null, row: null } },
  );
});

test("field checks run before the cross-field log-domain check", () => {
  // waist (42) < neck (45) would be LOG_DOMAIN, but weightKg 600 fails its
  // field range check first.
  assert.deepEqual(run({ ...man, neckCm: "45", waistCm: "42", weightKg: "600" }), {
    ok: false,
    error: { code: "RANGE", field: "weightKg", row: null },
  });
});

test("field order: sex ENUM beats a later field error", () => {
  assert.deepEqual(run({ ...man, sex: "Male", heightCm: "260" }), {
    ok: false,
    error: { code: "ENUM", field: "sex", row: null },
  });
});

test("field order: heightCm error beats a waistCm error", () => {
  assert.deepEqual(run({ ...man, heightCm: "260", waistCm: "85.55" }), {
    ok: false,
    error: { code: "RANGE", field: "heightCm", row: null },
  });
});

test("field order: hipCm NOT_APPLICABLE beats a weightKg error", () => {
  assert.deepEqual(run({ ...man, hipCm: "95", weightKg: "600" }), {
    ok: false,
    error: { code: "NOT_APPLICABLE", field: "hipCm", row: null },
  });
});

const errorCases = [
  ["empty height", { ...man, heightCm: "" }, { code: "EMPTY", field: "heightCm", row: null }],
  ["empty weight", { ...man, weightKg: "" }, { code: "EMPTY", field: "weightKg", row: null }],
  ["overlong height", { ...man, heightCm: "123456789" }, { code: "INPUT_LIMIT", field: "heightCm", row: null }],
  ["overlong sex", { ...man, sex: "maleXXXXX" }, { code: "INPUT_LIMIT", field: "sex", row: null }],
  ["overlong male hip", { ...man, hipCm: "123456789" }, { code: "INPUT_LIMIT", field: "hipCm", row: null }],
  ["lone high surrogate", { ...man, waistCm: "\uD800" }, { code: "UNICODE", field: "waistCm", row: null }],
  ["lone low surrogate", { ...man, waistCm: "\uDC00" }, { code: "UNICODE", field: "waistCm", row: null }],
  ["surrogate in sex", { ...man, sex: "\uD800" }, { code: "UNICODE", field: "sex", row: null }],
  ["leading zero", { ...man, heightCm: "0175" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["trailing dot", { ...man, heightCm: "175." }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["leading dot", { ...man, heightCm: ".5" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["two decimals via 0.x", { ...man, waistCm: "0.55" }, { code: "DECIMAL_FORMAT", field: "waistCm", row: null }],
  ["sign", { ...man, heightCm: "+175" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["space", { ...man, heightCm: " 175" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["exponent", { ...man, heightCm: "1e2" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["four integer digits", { ...man, heightCm: "1000" }, { code: "DECIMAL_FORMAT", field: "heightCm", row: null }],
  ["height just below range", { ...man, heightCm: "99.9" }, { code: "RANGE", field: "heightCm", row: null }],
  ["height just above range", { ...man, heightCm: "250.1" }, { code: "RANGE", field: "heightCm", row: null }],
  ["neck below range", { ...man, neckCm: "19.9" }, { code: "RANGE", field: "neckCm", row: null }],
  ["neck above range", { ...man, neckCm: "80.1" }, { code: "RANGE", field: "neckCm", row: null }],
  ["waist below range", { ...man, waistCm: "39.9" }, { code: "RANGE", field: "waistCm", row: null }],
  ["waist above range", { ...man, waistCm: "300.1" }, { code: "RANGE", field: "waistCm", row: null }],
  ["weight below range", { ...man, weightKg: "24.9" }, { code: "RANGE", field: "weightKg", row: null }],
  ["weight above range", { ...man, weightKg: "500.1" }, { code: "RANGE", field: "weightKg", row: null }],
  ["female hip below range", { ...woman, hipCm: "39.9" }, { code: "RANGE", field: "hipCm", row: null }],
  ["female hip above range", { ...woman, hipCm: "300.1" }, { code: "RANGE", field: "hipCm", row: null }],
  ["sex empty string is ENUM", { ...man, sex: "" }, { code: "ENUM", field: "sex", row: null }],
  ["sex wrong case is ENUM", { ...man, sex: "FEMALE" }, { code: "ENUM", field: "sex", row: null }],
  ["male hip with junk text is NOT_APPLICABLE (no grammar check)", { ...man, hipCm: "abc" }, { code: "NOT_APPLICABLE", field: "hipCm", row: null }],
];

for (const [name, input, error] of errorCases) {
  test(`validation: ${name}`, () => {
    assert.deepEqual(run(input), { ok: false, error });
  });
}

const schemaError = { ok: false, error: { code: "SCHEMA", field: null, row: null } };

test("schema: null, array, and non-object inputs", () => {
  assert.deepEqual(run(null), schemaError);
  assert.deepEqual(run([]), schemaError);
  assert.deepEqual(run("male"), schemaError);
  assert.deepEqual(run(42), schemaError);
  assert.deepEqual(run(undefined), schemaError);
});

test("schema: missing and extra fields", () => {
  const missing = { ...man };
  delete missing.weightKg;
  assert.deepEqual(run(missing), schemaError);
  assert.deepEqual(run({ ...man, age: "30" }), schemaError);
});

test("schema: wrongly typed field values", () => {
  assert.deepEqual(run({ ...man, heightCm: 175 }), schemaError);
  assert.deepEqual(run({ ...man, sex: null }), schemaError);
  assert.deepEqual(run({ ...man, hipCm: undefined }), schemaError);
});

test("schema: accessor-backed field", () => {
  const input = { ...man };
  Object.defineProperty(input, "heightCm", {
    enumerable: true,
    get() {
      return "175";
    },
  });
  assert.deepEqual(run(input), schemaError);
});

test("schema: throwing getter on an unrelated own key is not read", () => {
  // Exactly six own enumerable keys are required, so an extra key already
  // fails SCHEMA before any value is read.
  const input = { ...man };
  Object.defineProperty(input, "extra", {
    enumerable: true,
    get() {
      throw new Error("must not be read as a field");
    },
  });
  assert.deepEqual(run(input), schemaError);
});

// The SPEC's category table, restated in the test as the oracle for the
// sweep below (not imported from the product).
function expectedCategory(sex, pct) {
  const bounds = sex === "male" ? [2, 6, 14, 18, 25] : [10, 14, 21, 25, 32];
  const ids = ["below-essential", "essential", "athletes", "fitness", "average", "obese"];
  for (let i = 0; i < bounds.length; i += 1) {
    if (pct < bounds[i]) return ids[i];
  }
  return "obese";
}

test("invariants hold across a sweep of valid inputs", () => {
  let successes = 0;
  for (const sex of ["male", "female"]) {
    for (const waist of [45, 60, 75, 90, 110, 140, 180]) {
      for (const height of [150, 175, 200]) {
        const input = {
          sex,
          heightCm: String(height),
          neckCm: "35",
          waistCm: String(waist),
          hipCm: sex === "female" ? "95" : "",
          weightKg: "80",
        };
        const outcome = run(input);
        if (!outcome.ok) {
          assert.equal(outcome.error.code, "IMPLAUSIBLE_RESULT");
          continue;
        }
        successes += 1;
        const { bodyFatPct, category, fatMassKg, leanMassKg } = outcome.result;
        assert.ok(bodyFatPct > 0 && bodyFatPct < 75, `pct in gate: ${bodyFatPct}`);
        assert.equal(
          Math.round((fatMassKg + leanMassKg) * 10),
          800,
          "fat + lean equals the weight at one decimal",
        );
        assert.equal(category, expectedCategory(sex, bodyFatPct), "category matches rounded pct");
      }
    }
  }
  assert.ok(successes >= 20, `sweep produced ${successes} successes`);
});
